const TITLES={eng:{L1:"Theme & Central Idea",L2:"Text Evidence",L3:"Author's Purpose",L4:"Parts of Speech (Drag)",L5:"Context Clues",L6:"Sentence Structure",L7:"Fill in the Blank",L8:"Sentence Editing",L9:"Memory Match",L10:"Speed Challenge",L11:"Spelling: Academic Words",L12:"Spelling Drag: Word Parts"},math:{L1:"Integers",L2:"Ratios & Proportions",L3:"Expressions",L4:"One-Step Equations",L5:"Word Problems",L6:"Integer Memory Match",L7:"Equation Speed Problems"},sci:{L1:"Cells",L2:"Body Systems",L3:"Ecosystems",L4:"Forces & Motion"}};

function M(q,answer,b,c,d,explain){return {type:"mc",q,choices:[answer,b,c,d],answer,explain};}

const SEQUENCES={eng:{
L1:[
M("What is a theme in a literary text?","A broad message about life revealed by the text","A one-word topic named in the title","A list of every event in order","The place and time of the story","A theme is a complete insight about life, not merely a topic, summary, or setting."),
M("Which statement is written as a theme rather than a topic?","Courage grows when people act despite fear.","Courage","A girl enters a dark cave.","The cave is beneath a mountain.","The complete sentence expresses an insight about courage; the other choices name a topic or story details."),
M("Nico practices the violin after every mistake and finally performs the solo. Which theme is best supported?","Persistence can turn setbacks into achievement.","Music is always easy to learn.","Audiences dislike new performers.","Talent matters more than practice.","Nico's repeated practice after mistakes directly supports persistence leading to success."),
M("A passage explains that city trees cool sidewalks, absorb rainwater, and shelter birds. What is its central idea?","City trees provide several environmental benefits.","Birds build nests in branches.","Sidewalks become hot in summer.","Rain falls in many cities.","The central idea unites all three benefits instead of repeating only one supporting detail."),
M("Which detail best supports the theme 'Honesty can rebuild trust'?","After admitting she broke the model, Priya helps repair it and her friend forgives her.","Priya's model is painted blue and silver.","The friends meet in science class on Tuesday.","A shelf holds several other models.","The admission, repair, and forgiveness show honesty restoring the damaged relationship."),
M("Mara shares her lunch with a new student; later, that student includes Mara in a club. Which theme fits both events?","Kindness can create connection.","Lunch is the most important meal.","Clubs should meet after school.","New students never feel nervous.","The reciprocal acts connect kindness with the growth of a relationship."),
M("Two articles describe community gardens: one emphasizes fresh food and the other neighborhood cooperation. Which central idea connects them?","Community gardens can strengthen residents and their neighborhoods.","Every garden grows the same vegetables.","Only experts should manage gardens.","Neighborhoods need fewer shared spaces.","The answer synthesizes the articles' different benefits into one supported central idea."),
M("In a story, Elena hides a poor test grade, worries for days, then tells her father and feels relieved. Which detail most develops the theme that truth eases burdens?","Elena feels relief immediately after telling her father.","The test contains twenty questions.","Her backpack rests by the door.","Her father cooks dinner that evening.","The change from worry to relief after the confession directly develops the stated theme."),
M("A report describes declining bee numbers, causes such as habitat loss, and ways residents can plant native flowers. What is the central idea?","Bee populations face threats, but community actions can help.","All insects live in flower gardens.","Native flowers bloom only in spring.","Scientists count bees every afternoon.","The answer captures the problem, causes, and proposed response across the whole report."),
M("Jon refuses help while building a cart, but after it collapses he listens to his team and they succeed. Which theme is most precise?","Collaboration can succeed where prideful independence fails.","Carts should be built from stronger wood.","Teams never disagree about a plan.","Failure proves a goal is impossible.","Jon's failed isolation and later team success create a contrast that supports the precise theme."),
{type:"truefalse",q:"True or false: A single text can support more than one theme when each theme is backed by a pattern of details.",answer:true,explain:"Grade-level literary analysis permits multiple themes, but each inference must be grounded in recurring textual evidence."},
M("A character returns a lost wallet despite needing money. Later she declines credit for a group success. What theme is supported by both choices?","Integrity means doing what is right without seeking personal gain.","Money causes every conflict.","Recognition is required for good work.","Lost objects are usually returned.","Both actions show principled behavior when reward or recognition could have benefited the character."),
M("Passage A shows a runner adapting after an injury. Passage B shows a town rebuilding after a flood. Which shared theme is strongest?","Resilience involves adjusting and continuing after hardship.","Sports and construction use identical skills.","Natural disasters always improve towns.","Injuries are worse than property damage.","Both texts center on adapting and continuing after a serious setback."),
M("A narrator repeatedly notices an empty chair after her sister leaves for college. What theme does that motif most likely develop?","Change can make absence feel present in everyday life.","Furniture should be replaced often.","College students dislike visiting home.","The narrator wants a larger room.","The repeated empty chair symbolizes how the sister's absence shapes ordinary experience."),
M("An essay presents rising library visits, quotes patrons, and describes expanded programs. Which central idea is best supported?","Expanded services have made the library a more active community resource.","Libraries should remove all printed books.","Every patron attends the same program.","Visitor totals never change over time.","The statistics, testimony, and program descriptions together show increased community use."),
M("A hero wins a race by ignoring an injured competitor, but feels ashamed and returns the medal. Which theme accounts for the resolution?","A victory without compassion may not feel honorable.","Winning always resolves internal conflict.","Athletes should never enter races.","Medals are more valuable than friendships.","Returning the medal resolves the hero's shame and reveals that compassion matters more than the hollow win."),
M("Across a novel, a locked gate first represents exclusion, later safety, and finally fear. Which theme is developed by the changing symbol?","Protection can become confinement when fear controls decisions.","All gates have only one meaning.","Safety requires avoiding every risk.","The setting never affects theme.","The gate's shift from protection to fear-driven restriction develops the tension between safety and confinement."),
M("Text A argues failure teaches useful lessons; Text B shows repeated failure causing a character to abandon an unsafe plan. Which nuanced shared theme fits both?","Failure can guide growth by revealing when to persist and when to change course.","Persistence is correct in every situation.","Abandoning a plan always shows weakness.","Failure has no value unless success follows.","The theme preserves both texts' evidence: failure informs either renewed effort or a wiser change."),
M("A memoir's opening shows the author ashamed of her accent; its ending shows her using two languages to negotiate peace. Which thematic claim best traces the change?","A trait once viewed as a weakness can become a source of agency.","Language differences inevitably create conflict.","The author forgets her childhood embarrassment.","Negotiation succeeds only when people agree.","The beginning-to-ending contrast shows a formerly rejected trait becoming empowering."),
M("A story praises ambition but shows the protagonist lose friends by pursuing recognition at any cost. Which theme best reflects that complexity?","Ambition can inspire achievement, yet unchecked ambition can damage relationships.","Ambition is entirely harmful.","Recognition guarantees lasting friendship.","Achievement and relationships never conflict.","The answer accounts for both the positive portrayal of drive and the consequences of excess." )
],
L2:[
M("Which choice is text evidence?","A specific quotation or paraphrased detail from the source","A guess made before reading","A feeling unrelated to the source","A fact from an unknown different text","Text evidence comes from the source being analyzed and directly supports a response."),
M("Which sentence best introduces evidence in a response?","The passage states that the trail 'reopened after volunteers repaired it.'","I just know the trail became better.","Everyone must agree with my opinion.","Trails are interesting for many reasons.","The sentence identifies the passage and integrates a precise quotation."),
M("Claim: The storm surprised the campers. Which detail is strongest evidence?","The forecast predicted clear skies, and the campers had packed no rain gear.","The campers carried blue backpacks.","The storm lasted for forty minutes.","The campsite had six wooden tables.","The inaccurate forecast and missing rain gear directly demonstrate that the storm was unexpected."),
M("Why should a reader explain evidence after quoting it?","To show how the detail supports the response","To increase the response's word count","To replace the original claim","To avoid identifying the source","Commentary makes the logical connection between the cited detail and the writer's claim explicit."),
M("Claim: The speaker values patience. Which quotation best supports it?","'I waited through three silent seasons, trusting the seeds below.'","'The red pot stood beside the door.'","'My neighbor owned a silver rake.'","'At noon, a truck passed the garden.'","Waiting through seasons while maintaining trust directly conveys patience."),
M("A student claims that Laila is resourceful. Which evidence is most relevant?","When the flashlight fails, Laila reflects sunlight with a mirror to signal rescuers.","Laila's cousin prefers strawberry ice cream.","The rescue station was built in 1998.","A storm cloud appears beyond the ridge.","Inventing a signal from available objects is a specific example of resourcefulness."),
M("Which response uses evidence and commentary effectively?","Mina is cautious because she 'tests each knot twice,' a habit that prevents equipment failure.","Mina is cautious. 'Tests each knot twice.'","'Tests each knot twice,' and that is a quotation.","Mina is cautious because I would be cautious too.","The answer presents a claim, embeds evidence, and explains the evidence's consequence."),
M("A passage says a wetland stores floodwater and filters pollutants. Which paraphrase best supports the claim that wetlands protect communities?","Wetlands reduce flooding and improve water quality.","Wetlands are areas that contain water.","Some communities are built near wetlands.","Pollutants can enter rivers after storms.","The paraphrase accurately combines the two protective functions without distorting the passage."),
M("Which evidence is most credible for a response about the school's energy use?","The district's audited report lists monthly electricity consumption.","A student guesses that lights use most energy.","An advertisement says its bulbs are the best.","An anonymous comment calls the building wasteful.","An audited, directly relevant district record provides verifiable data about actual use."),
M("Claim: The setting feels isolated. Which pair of details gives the strongest support?","The nearest house is fifty miles away, and the radio receives only static.","The cabin has a green door, and a clock hangs inside.","The character wakes early and drinks tea.","Snow began in January, and winter was cold.","Distance from others plus failed communication jointly create isolation."),
{type:"truefalse",q:"True or false: Evidence supports a response only when the writer also makes clear how that evidence connects to the claim.",answer:true,explain:"Relevant evidence and explanatory commentary work together; an unexplained quotation does not establish the reasoning by itself."},
M("Claim: The council's decision changed after public testimony. Which evidence would be sufficient?","Minutes showing an initial no vote, testimony concerns, and a later revised yes vote","A photo of the council chamber before the meeting","A resident's statement that meetings are usually long","The printed names of all council members","The sequence in the official minutes documents both the earlier position and the change following testimony."),
M("A source calls the invention 'revolutionary,' but provides no data. What evidence should a careful response seek?","Independent results comparing the invention with existing designs","More promotional adjectives from the inventor","The color chosen for the prototype","A rumor about future sales","Independent comparative results can verify the source's broad claim rather than merely repeat it."),
M("Which quotation best supports an inference that Theo is concealing fear?","'Theo laughed too loudly, then checked the locked window for the fourth time.'","'Theo wore a jacket with deep pockets.'","'The room had two windows and one door.'","'Theo arrived shortly before sunset.'","The forced laugh and repeated checking indirectly reveal anxiety despite his outward behavior."),
M("Two sources disagree about a dam. Which response uses evidence fairly?","Source A cites lower flood peaks, while Source B documents lost fish habitat; together they show a tradeoff.","Source A is correct because it appears first.","Source B must be wrong because it criticizes the dam.","Both sources say exactly the same thing.","The response accurately represents distinct evidence from both sources and draws a balanced conclusion."),
M("A student argues that a narrator is unreliable. Which evidence-and-reasoning pair is strongest?","The narrator denies entering the room, but later describes an object visible only inside; the contradiction weakens credibility.","The narrator uses long sentences; long sentences are always untrue.","Another character dislikes the narrator; disliked people always lie.","The story is fictional; therefore no narrator can be trusted.","A concrete contradiction in the narrator's own account directly supports an inference of unreliability."),
M("Which revision most precisely links evidence to the claim that the policy improved attendance?","Attendance rose from 86% to 93% during the semester after the policy began, a seven-point increase consistent with improvement.","Attendance changed after the policy, which proves everything improved.","The policy was announced in August, and announcements are effective.","Many people liked the policy, so attendance must have risen.","The revision cites exact before-and-after data and explains the measured change without overstating it."),
M("A historical letter reports food shortages, while a later textbook says supplies were adequate. What is the best evidence-based response?","Compare the authors' dates, locations, purposes, and corroborating records before deciding which claim applies.","Always accept the newer source without checking it.","Always accept a firsthand source as completely unbiased.","Average the two claims even though they are qualitative.","Source context and corroboration help explain disagreement and determine the scope and reliability of each account."),
M("Which evidence most strongly tests the claim that a new bus route shortened commutes for most riders?","Matched travel-time records for a representative sample before and after the route change","One rider's shortest trip on opening day","The route map's use of a straighter blue line","A news headline calling the route efficient","Representative paired records measure the claimed change for riders rather than an isolated case or impression."),
M("A response claims a poem celebrates freedom, yet its repeated images are locked doors and clipped wings. What should the writer do?","Revise the claim to account for the poem's tension between longing for freedom and confinement.","Keep the claim and omit the conflicting images.","Replace the poem's words with more positive ones.","Use only the title as evidence.","Strong interpretation adjusts to the full evidence, including details that complicate the original claim." )
],
L3:[
M("What does an author's purpose describe?","The reason the author created the text","The number of paragraphs in the text","The reader's favorite sentence","The date the text was assigned","Purpose concerns what the author intends to accomplish through the text."),
M("A manual lists numbered steps for resetting a router. What is its primary purpose?","To instruct readers how to complete a task","To entertain readers with a fictional conflict","To persuade readers to ban technology","To describe the author's childhood","Numbered procedures and commands signal an instructional purpose."),
M("An article explains how eclipses occur using diagrams and definitions. What is its primary purpose?","To inform readers about a scientific process","To sell tickets to an eclipse event","To criticize readers who ask questions","To narrate an imaginary adventure","Explanations, definitions, and diagrams are evidence of an informative purpose."),
M("A poster urges residents to conserve water and lists three actions. What is its purpose?","To persuade residents to change their behavior","To entertain residents with a mystery","To record a private memory","To compare two fictional characters","The call to action and supporting steps are intended to influence behavior."),
M("A humorous story builds toward an unexpected punch line. What is its main purpose?","To entertain the audience","To provide laboratory directions","To report unbiased survey results","To request official records","Comic plot and a punch line primarily seek to amuse."),
M("A principal's letter explains a schedule change and asks families to arrive ten minutes earlier. Which purposes work together?","To inform families and prompt a specific action","To entertain families and hide the schedule","To describe a setting and create suspense","To criticize transportation and tell a joke","The letter supplies information and also requests changed behavior."),
M("An author describes a polluted stream, cites health data, and ends with 'Support the cleanup bond.' What is the dominant purpose?","To persuade readers to support the bond","To teach readers how to test water","To entertain readers with fantasy","To list every stream in the state","Problem evidence followed by a direct appeal is structured to persuade."),
M("Why might an author include a personal anecdote in an informational article about dyslexia?","To humanize the facts and help readers connect with the message","To make all research evidence unnecessary","To prove every person has the same experience","To change the article into fictional drama","A relevant personal experience can make factual information concrete without replacing evidence."),
M("A museum brochure uses vivid descriptions beside hours and ticket prices. What combined purpose is most likely?","To inform visitors and encourage them to attend","To conceal when the museum opens","To argue that museums should close","To teach curators how to preserve artifacts","Practical details inform, while appealing description promotes attendance."),
M("An editorial repeats the question 'What kind of city will we leave behind?' Why?","To push readers to consider responsibility and accept the argument","To request a literal one-word answer","To provide a neutral definition of city","To interrupt the argument with an unrelated idea","The rhetorical question directs readers toward the editorial's persuasive message."),
{type:"truefalse",q:"True or false: An author may pursue more than one purpose, but textual features can reveal which purpose is dominant.",answer:true,explain:"Texts often blend purposes; the dominant purpose is identified by the overall structure, evidence, tone, and requested response."},
M("A satirical article praises a town's 'brilliant' plan to replace every tree with parking. What purpose does the irony serve?","To criticize the plan by making its flaws appear absurd","To provide literal praise for removing trees","To give technical paving instructions","To neutrally classify tree species","The exaggerated praise means the opposite and exposes the policy's environmental flaw."),
M("A biography focuses on failed experiments before a discovery. What message is the author likely advancing?","Scientific progress often depends on learning from failure","Successful scientists never make mistakes","Discovery occurs without sustained effort","Experiments are less useful than guesses","The selection and emphasis of repeated failures frame them as necessary steps toward progress."),
M("An article opens with a dramatic rescue, then explains flood-warning technology. Why use that structure?","The rescue creates urgency before the author explains the informative content","The rescue proves technology never fails","The structure hides the article's subject","The opening eliminates the need for facts","The narrative hook engages readers and shows the real stakes of the later explanation."),
M("A speech uses inclusive words such as 'we' and 'our future.' How do they support purpose?","They build shared identity to strengthen a persuasive appeal","They make the speaker's evidence automatically true","They signal that the speech is a private diary","They remove responsibility from the audience","Inclusive pronouns position speaker and audience as members of the same group with a shared stake."),
M("A company-funded article minimizes risks and emphasizes benefits. What should a reader infer about purpose?","The sponsor may be trying to shape opinion in favor of its product","Funding guarantees the article is false","The article can have no informative content","The sponsor has no possible effect on framing","The source's interest may influence which evidence is emphasized, so persuasive intent deserves scrutiny."),
M("In a memoir, the author admits earlier prejudice and traces how relationships changed her. What message is most supported?","Honest self-examination can lead to growth","People cannot revise deeply held beliefs","Memoirs should avoid uncomfortable memories","Relationships always eliminate disagreement","The author selects an acknowledged flaw and a documented change to present reflection as a path to growth."),
M("A climate infographic uses a red upward arrow, a compressed time scale, and the command 'Act now.' How do these choices advance purpose?","They heighten urgency to persuade viewers toward action","They make the data independent of scale","They turn the infographic into a fictional narrative","They prove the source has no viewpoint","Color, scale, and imperative language frame the information as an urgent persuasive appeal."),
M("An author presents a counterargument fairly before rebutting it with evidence. What purpose does this choice serve?","It increases credibility and strengthens the author's persuasive case","It shows the author has abandoned the original claim","It changes persuasion into pure entertainment","It guarantees every reader will agree","Acknowledging a plausible alternative signals fairness and lets evidence answer the opposition directly."),
M("A text appears to inform about nutrition but links every recommendation to one brand's store. Which conclusion best accounts for purpose?","Its informational surface also serves a commercial persuasive purpose","The links prove the nutrition facts are complete","Commercial goals cannot coexist with information","The author's only purpose is to define nutrition","Brand-specific calls to purchase reveal a promotional aim layered onto the informational content." )
],
L4:[
M("In 'The curious fox listened,' what part of speech is 'curious'?","Adjective","Adverb","Noun","Preposition","Curious modifies the noun fox, so a dictionary would label it an adjective."),
M("In 'The river flows swiftly,' what part of speech is 'swiftly'?","Adverb","Adjective","Pronoun","Conjunction","Swiftly modifies the verb flows and tells how, making it an adverb."),
M("In 'They carried the lantern,' what part of speech is 'lantern'?","Noun","Verb","Adverb","Interjection","Lantern names a thing and functions as the direct object, so it is a noun."),
M("In 'Birds migrate each autumn,' what part of speech is 'migrate'?","Verb","Noun","Adjective","Preposition","Migrate expresses the action performed by birds, so it is a verb."),
M("Which dictionary label identifies 'beneath' in 'beneath the bridge'?","Preposition","Pronoun","Adverb only","Coordinating conjunction","Beneath begins a phrase showing the relationship between an implied action and the bridge."),
M("The word 'record' in 'Please record the results' is which part of speech?","Verb","Noun","Adjective","Conjunction","Here record names the requested action; its sentence role is a verb."),
M("The word 'record' in 'The record is incomplete' is which part of speech?","Noun","Verb","Adverb","Preposition","The article the and subject position show that record names a thing, so it is a noun."),
M("In 'Before lunch, we rehearsed,' how is 'before' used?","Preposition","Adjective","Pronoun","Interjection","Before takes the object lunch, forming a prepositional phrase."),
M("In 'We had met before,' how is 'before' used?","Adverb","Preposition","Noun","Conjunction","With no object following it, before modifies had met by indicating when."),
M("Which resource entry best helps verify that 'conduct' changes pronunciation by part of speech?","An entry with pronunciation guides and noun/verb labels","A page showing only synonyms","A map of word frequency","A list with no usage examples","Pronunciation symbols paired with part-of-speech labels show the noun-verb stress shift directly."),
{type:"truefalse",q:"True or false: A word's part of speech can change when its function changes from one sentence to another.",answer:true,explain:"English conversion allows forms such as 'paint' to function as a noun in one context and a verb in another."},
M("In 'The light backpack felt comfortable,' which analysis of 'light' is correct?","It is an adjective modifying backpack.","It is a noun serving as the subject.","It is an adverb modifying felt.","It is a verb meaning illuminate.","Sentence position and meaning show light describing the noun backpack's weight."),
M("In 'Please light the candle,' which analysis of 'light' is correct?","It is a verb naming the requested action.","It is an adjective modifying candle.","It is a preposition showing location.","It is a pronoun replacing candle.","After please, light functions as the base-form verb for the action to perform."),
M("A dictionary lists 'close' as adjective /klohs/ and verb /klohz/. Which sentence uses the adjective?","The finish line is close.","Close the window quietly.","Workers close the shop at nine.","Please close every lid.","After the linking verb is, close describes the location of the finish line and uses the adjective pronunciation."),
M("In 'Since the road flooded, buses turned back,' what part of speech is 'since'?","Subordinating conjunction","Preposition","Adjective","Interjection","Since introduces a dependent clause with its own subject and verb, linking cause to the main clause."),
M("Which dictionary evidence would resolve whether 'desert' means abandon or dry land?","The pronunciation, definition, and part-of-speech entry matching its sentence","The word's alphabetical position only","The length of the dictionary page","The color of the entry heading","The verb and noun have different meanings and stress patterns, so all three entry features identify the intended use."),
M("In 'That claim is suspect,' a learner thinks 'suspect' is always a noun. Which evidence best corrects the error?","The entry labels an adjective meaning doubtful and gives a matching example.","The entry lists suspect before suspicion alphabetically.","The word contains two syllables.","Another dictionary uses a blue font.","A labeled adjective sense that fits the sentence demonstrates the word's context-dependent function."),
M("In 'After we object, the object may be removed,' which analysis is accurate?","The first is a verb; the second is a noun.","Both are nouns with identical stress.","The first is an adjective; the second is an adverb.","Both are prepositions.","Object names an action after the subject we, then names a thing after the article the."),
M("A learner needs the origin and current part of speech of 'benevolent.' Which resource result is most useful?","An etymology tracing Latin bene plus velle and labeling the word adjective","A rhyming list without definitions","A translation of an unrelated sentence","A search result that shows only advertisements","The etymology answers origin, while the grammatical label verifies current part of speech."),
M("In 'I will present the present at noon,' why do dictionary entries show two pronunciations?","The verb and noun use different stress patterns and functions.","Every repeated word must change spelling.","No English word can have multiple parts of speech.","The second form is necessarily a typographical error.","Present is stressed differently when it acts as a verb and when it names a gift as a noun." )
]
},math:{},sci:{}};

